FUNCTION_BLOCK FB_S08
VAR_INPUT
    RecipeSelect : INT;
    ChangeoverReq : BOOL;
    PartHeight : REAL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    ActiveRecipe : INT := 1;
    SortLeft : BOOL := FALSE;
    SortRight : BOOL := FALSE;
    Busy : BOOL := FALSE;
    Status : WORD := 16#0000;
END_VAR
VAR
    ChangeoverReqLast : BOOL := FALSE;
    ChangeoverRise : BOOL := FALSE;
    StartupScans : INT := 0;
    BusyScans : INT := 0;
    LeftThreshold : REAL := 30.0;
    RightThreshold : REAL := 60.0;
    RecipeValid : BOOL := FALSE;
    BusyAtScanStart : BOOL := FALSE;
END_VAR

(*
需求原文：
分拣线按产品高度分到左右两条支线，阈值来自配方。
切换配方必须在线上无料时进行。
1. 配方1：左30 / 右60 mm；配方2：左50 / 右90 mm；
   配方3：左70 / 右120 mm。
2. ChangeoverReq上升沿且非忙、PartHeight=0.0时切换，
   Busy保持2 s后自动清除。
3. Busy期间禁止两路分拣。
4. 非法RecipeSelect拒绝切换，ActiveRecipe保持，Status=16#8801。
5. 低于左阈值分左；左阈值至右阈值之间分右；
   超过右阈值不动作，Status=16#8802。
6. 上电ActiveRecipe=1，Busy=FALSE。

待审语义冲突及边界：
- C9为G(Busy -> G[0,100](Busy))。其全局滚动约束意味着
  Busy一旦为TRUE便不能再次清除，与原文2 s自动清除矛盾。
  本实现保留原文的有限2 s计时，不能同时满足C9。
- C10的闭区间[0,1]要求前两次调用保持初态；原文未明确
  上电调用中的有效请求是否可立即处理。本实现采用C10，
  前两次调用禁止分拣和切换，并持续采样请求边沿。
- PartHeight恰等于右阈值时，原文既不属于右分拣区间，
  也不满足“超过右阈值”。本实现不动作且不报超规格，
  此边界仍待需求确认。
- EStop_NC的状态码、复位及计时行为未规定。本实现急停时
  禁止分拣和新切换，不改配方，已启动的2 s计时继续。
- 无料或非正高度不分拣；非法配方错误优先于超规格错误。
- 固定20 ms扫描计数实现2 s；启动扫描计数为0，
  其后第100次调用清除Busy。未声称已编译或逐周期验证。
*)

ChangeoverRise := ChangeoverReq AND NOT ChangeoverReqLast;
ChangeoverReqLast := ChangeoverReq;
RecipeValid := (RecipeSelect >= 1) AND (RecipeSelect <= 3);

SortLeft := FALSE;
SortRight := FALSE;
Status := 16#0000;

IF StartupScans < 2 THEN
    ActiveRecipe := 1;
    Busy := FALSE;
    BusyScans := 0;
    StartupScans := StartupScans + 1;
ELSE
    BusyAtScanStart := Busy;

    (* 先推进既有切换；完成扫描不接受新的切换请求。 *)
    IF BusyAtScanStart THEN
        IF BusyScans < 100 THEN
            BusyScans := BusyScans + 1;
        END_IF;
        IF BusyScans >= 100 THEN
            Busy := FALSE;
            BusyScans := 0;
        END_IF;
    END_IF;

    IF NOT RecipeValid THEN
        Status := 16#8801;
    END_IF;

    IF EStop_NC
       AND ChangeoverRise
       AND RecipeValid
       AND NOT BusyAtScanStart
       AND (PartHeight = 0.0) THEN
        ActiveRecipe := RecipeSelect;
        Busy := TRUE;
        BusyScans := 0;
    END_IF;

    CASE ActiveRecipe OF
        1:
            LeftThreshold := 30.0;
            RightThreshold := 60.0;
        2:
            LeftThreshold := 50.0;
            RightThreshold := 90.0;
        3:
            LeftThreshold := 70.0;
            RightThreshold := 120.0;
    END_CASE;

    IF EStop_NC AND NOT Busy AND (PartHeight > 0.0) THEN
        IF PartHeight < LeftThreshold THEN
            SortLeft := TRUE;
        ELSIF PartHeight < RightThreshold THEN
            SortRight := TRUE;
        ELSIF PartHeight > RightThreshold THEN
            IF RecipeValid THEN
                Status := 16#8802;
            END_IF;
        END_IF;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
